function GachaponCheckCache:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local initParams = self.controller.Argument.parameters
        self.stashedResultData_ = clone(initParams.stashedData)
        self.currentResultData_ = clone(initParams.currentData)
        self.stashedConfirmCb_  = initParams.stashedCb
        self.currentConfirmCb_  = initParams.currentCb
        self.isFinalDecision_   = initParams.isFinal
        table.sort(self.stashedResultData_, function(aResult, bResult)
            local aCardVo = CardConfMgr:GetInstance():GetCardByRefId(aResult.goodsId)
            local bCardVo = CardConfMgr:GetInstance():GetCardByRefId(bResult.goodsId)
            return checkInt(aCardVo.rare) > checkInt(bCardVo.rare)
        end)
        table.sort(self.currentResultData_, function(aResult, bResult)
            local aCardVo = CardConfMgr:GetInstance():GetCardByRefId(aResult.goodsId)
            local bCardVo = CardConfMgr:GetInstance():GetCardByRefId(bResult.goodsId)
            return checkInt(aCardVo.rare) > checkInt(bCardVo.rare)
        end)
    end))
    return coWait
end


