        SetButtonAction(self.RConfirmBtn, function()
            local confirmTips = localize("是否确认使用本轮的召唤结果？")
            GameUtils.SecondConfirm(confirmTips, function()
                if self.currentConfirmCb_ then
                    self.currentConfirmCb_()
                end
                self.controller:Close()
            end)
        end)

        -- 刷新结果
        self:RefreshResultData(true)
        self:RefreshResultData(false)

        GachaponUtils.ResetCameraData(URPCameraController.Instance.uiCamera)
    end))
    return coWait
end


---@param isCurrent boolean
function GachaponCheckCache:RefreshResultData(isCurrent)
    local cellGrid      = isCurrent and self.RCellGrid or self.LCellGrid
    local gridCell      = isCurrent and self.RGridCell or self.LGridCell
    local cellNode1     = isCurrent and self.RGachaCell1 or self.LGachaCell1
    local cellNode2     = isCurrent and self.RGachaCell2 or self.LGachaCell2
    local cellLayer1    = isCurrent and self.RCellLayer1 or self.LCellLayer1
    local cellLayer2    = isCurrent and self.RCellLayer2 or self.LCellLayer2
    local displayData   = isCurrent and self.currentResultData_ or self.stashedResultData_
    local displayCount  = #displayData
    local result1CardVo = CardConfMgr:GetInstance():GetCardByRefId(displayData[1].goodsId)
    local result2CardVo = CardConfMgr:GetInstance():GetCardByRefId(displayData[2].goodsId)
    local isDoubleNode  = result1CardVo.rare == Constants.RareType.SSR and result2CardVo.rare == Constants.RareType.SSR
    
    -- update cellNode1
    KTool.SetActive(cellLayer1, true)
    self:RefreshGachaCellNode(cellNode1, 1, isCurrent)
    
    -- update cellNode2
    KTool.SetActive(cellLayer2, isDoubleNode)
    if isDoubleNode then
        self:RefreshGachaCellNode(cellNode2, 2, isCurrent)
    end
    
    -- update cellGrid
    KTool.SetActive(gridCell, false)
    local gridIdxOffset = isDoubleNode and 2 or 1
    local gridCellCount = displayCount - gridIdxOffset
    GachaponUtils.ResizeContent(cellGrid, gridCellCount, gridCell)
    for gridIndex = 1, gridCellCount do
        local cellTrans = cellGrid:GetChild(gridIndex - 1)
        self:RefreshGachaCellNode(cellTrans, gridIdxOffset + gridIndex, isCurrent)
    end
end


---@param cellTrans UnityEngine.Transform
---@param dataIndex integer @ 1-len
---@param isCurrent boolean
function GachaponCheckCache:RefreshGachaCellNode(cellTrans, dataIndex, isCurrent)
    local displayData = isCurrent and self.currentResultData_ or self.stashedResultData_
    local resultData  = displayData[dataIndex]

    local cardId   = resultData.goodsId
    local cardVo   = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    local mainCell = cellTrans:Find("CellMain")

    -- 更新卡牌形象
    ---@type CardSkinVo
    local roleSkinVo  = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
    local roleImgComp = mainCell:Find("CardGroup/charact").gameObject:GetComponent(typeof(RawImageAlterable))
    roleImgComp:LoadSprite(roleSkinVo.cardHeadList)

    -- 更新卡牌背景
    mainCell:Find("CardGroup/ImgBgCard1").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare
    mainCell:Find("CardGroup/ImgBgCard2").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare
    mainCell:Find("CardGroup/ImgBgCard3").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare
    
    -- 更新卡牌品质
    mainCell:Find("CardGroup/AnimRoot/Rare/ImgRareBgMask/ImgRareBg").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare
    mainCell:Find("CardGroup/AnimRoot/Rare/Node/ImgRareIcon").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare
    mainCell:Find("CardGroup/AnimRoot/Rare/Node/ImgRareIcon2").gameObject:GetComponent(typeof(UISwitchImage)).Status = cardVo.rare

    -- 更新卡牌属性
    local attrIconPath = CardUtils.GetCardAttrIconPath(cardVo.attributeType)
    local attrIconComp = mainCell:Find("CardGroup/ProfessionalGroup/ImgElement").gameObject:GetComponent(typeof(ImageComp))
    GachaponShared:LoadSpriteAsync(attrIconComp, attrIconPath)
    
    -- 更新卡牌类型
    local typeIconPath = CardConfMgr:GetInstance():GetCardCareerIconByType(cardVo.career)
    local typeIconComp = mainCell:Find("CardGroup/ProfessionalGroup/ImgType").gameObject:GetComponent(typeof(ImageComp))
    GachaponShared:LoadSpriteAsync(typeIconComp, typeIconPath)

    -- 播放出场动画
    local cellAnim = cellTrans.gameObject:GetComponent(typeof(Animator))
    cellAnim:Play("Default")

    -- add click callback
    SetButtonAction(mainCell, function()
        GachaponUtils.OpenDetail(cardId)
    end)
end


return GachaponCheckCache
